package com.auth.repository;

import com.auth.entity.TokenEntity;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

@Repository
public interface TokenRepository extends JpaRepository<TokenEntity, Long> {

    Optional<TokenEntity> findByTokenValue(String tokenValue);

    List<TokenEntity> findByUserIdAndTokenType(String userId, String tokenType);

    @Modifying
    @Query("UPDATE TokenEntity t SET t.isRevoked = true WHERE t.userId = :userId")
    void revokeAllTokensByUser(@Param("userId") String userId);

    @Modifying
    @Query("UPDATE TokenEntity t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue")
    void consumeToken(@Param("tokenValue") String tokenValue);

    // Find tokens that are expired or revoked for cleanup
    @Query("SELECT t FROM TokenEntity t WHERE t.expiresAt < CURRENT_TIMESTAMP OR t.isRevoked = true OR t.isConsumed = true")
    List<TokenEntity> findAllExpiredOrRevokedOrConsumed();
}
