package com.auth.service;

import com.auth.entity.TokenEntity;
import com.auth.repository.TokenRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    // Login - generates tokens atomically
    @Transactional
    public String login(String username, String password) {
        // Check credentials - accept any non-empty username and password combination
        if (username == null || username.isEmpty() || password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Username and password must be non-empty");
        }

        // Generate random tokens
        String accessToken = generateToken("ACCESS");
        String refreshToken = generateToken("REFRESH");
        String oneTimeToken = generateToken("ONETIME");

        LocalDateTime now = LocalDateTime.now();
        LocalDateTime accessExpires = now.plusMinutes(10);
        LocalDateTime refreshExpires = now.plusDays(1);
        LocalDateTime oneTimeExpires = now.plusMinutes(5);

        // Store all tokens atomically
        tokenRepository.save(new TokenEntity(accessToken, username, "ACCESS", now, accessExpires, false, false));
        tokenRepository.save(new TokenEntity(refreshToken, username, "REFRESH", now, refreshExpires, false, false));
        tokenRepository.save(new TokenEntity(oneTimeToken, username, "ONETIME", now, oneTimeExpires, false, false));

        // Return accessToken for the response (oneTimeToken is also needed)
        // Actually the login response needs both accessToken and oneTimeToken
        // Let me return a response object from controller instead
        return accessToken; // Just for internal use
    }

    private String generateToken(String type) {
        // Generate a unique token string
        return UUID.randomUUID().toString();
    }

    // Renew - check refresh token from cookie or header
    @Transactional
    public String renew(String refreshTokenValue, String userId) {
        // Find the refresh token
        TokenEntity existingRefresh = tokenRepository.findByTokenValue(refreshTokenValue)
            .orElseThrow(() -> new RuntimeException("Refresh token not found"));

        // Check if it's valid - not revoked, not expired
        if (existingRefresh.isRevoked() || existingRefresh.getExpiresAt().isBefore(LocalDateTime.now())) {
            throw new RuntimeException("Refresh token is invalid (revoked or expired)");
        }

        // Atomically:
        // 1. Revoke the old refresh token
        // 2. Create new refresh token
        // 3. Create new access token
        // All in one transaction

        // First, mark old as revoked
        existingRefresh.setRevoked(true);
        tokenRepository.save(existingRefresh); // This updates the existing entity

        // Generate new tokens
        String newRefreshToken = generateToken("REFRESH");
        String newAccessToken = generateToken("ACCESS");
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime newRefreshExpires = now.plusDays(1);
        LocalDateTime newAccessExpires = now.plusMinutes(10);

        tokenRepository.save(new TokenEntity(newRefreshToken, userId, "REFRESH", now, newRefreshExpires, false, false));
        tokenRepository.save(new TokenEntity(newAccessToken, userId, "ACCESS", now, newAccessExpires, false, false));

        return newAccessToken;
    }

    // Validate one-time token
    @Transactional
    public boolean validateOneTimeToken(String tokenValue, String userId) {
        // Find the token
        TokenEntity token = tokenRepository.findByTokenValue(tokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        // Check if it belongs to the user
        if (!token.getUserId().equals(userId)) {
            // This might not be needed if we trust the tokenValue contains user info, but we check userId from request
            // Actually the validate endpoint might not pass userId - let me check requirements
            // "Accept one-time token as a JSON parameter." - it doesn't include username
            // But the token itself is associated with a user in DB
            // The validation just checks if the token exists and is valid, doesn't verify user
            // Let me re-read: "validate and consume one-time tokens" - it doesn't say checking user
            // So we just validate the token itself
        }

        // Check not revoked, not expired, not consumed
        if (token.isRevoked() || token.getExpiresAt().isBefore(LocalDateTime.now()) || token.isConsumed()) {
            return false;
        }

        // Atomically mark as consumed - update the entity and return true
        token.setConsumed(true);
        tokenRepository.save(token); // This will atomically update
        return true;
    }

    // Logout - revoke all tokens for user
    @Transactional
    public void logout(String userId, String accessTokenValue) {
        // First validate the access token
        TokenEntity accessToken = tokenRepository.findByTokenValue(accessTokenValue)
            .orElseThrow(() -> new RuntimeException("Access token not found"));

        if (!accessToken.getUserId().equals(userId) || accessToken.isRevoked() || accessToken.getExpiresAt().isBefore(LocalDateTime.now())) {
            throw new RuntimeException("Invalid access token");
        }

        // Revoke all tokens for this user
        tokenRepository.revokeAllTokensByUser(userId);
    }
}
EOF"}

