package com.auth.controller;

import com.auth.dto.LoginRequest;
import com.auth.dto.LoginResponse;
import com.auth.dto.ValidateTokenResponse;
import com.auth.entity.TokenEntity;
import com.auth.repository.TokenRepository;
import com.auth.service.AuthService;
import org.springframework.http.Cookie;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.time.LocalDateTime;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;
    private final TokenRepository tokenRepository;

    public AuthController(AuthService authService, TokenRepository tokenRepository) {
        this.authService = authService;
        this.tokenRepository = tokenRepository;
    }

    // POST /api/auth/login
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        if (request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body("Username and password must be non-empty");
        }

        // Generate tokens atomically
        String accessToken = generateToken("ACCESS");
        String refreshToken = generateToken("REFRESH");
        String oneTimeToken = generateToken("ONETIME");

        LocalDateTime now = LocalDateTime.now();
        LocalDateTime accessExpires = now.plusMinutes(10);
        LocalDateTime refreshExpires = now.plusDays(1);
        LocalDateTime oneTimeExpires = now.plusMinutes(5);

        tokenRepository.save(new TokenEntity(accessToken, request.getUsername(), "ACCESS", now, accessExpires, false, false));
        tokenRepository.save(new TokenEntity(refreshToken, request.getUsername(), "REFRESH", now, refreshExpires, false, false));
        tokenRepository.save(new TokenEntity(oneTimeToken, request.getUsername(), "ONETIME", now, oneTimeExpires, false, false));

        LoginResponse response = new LoginResponse(accessToken, oneTimeToken);
        // Set refresh token cookie
        Cookie refreshTokenCookie = new Cookie("refreshToken", refreshToken);
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400); // 24 hours
        return ResponseEntity.ok()
            .header("Set-Cookie", refreshTokenCookie.toString())
            .body(response);
    }

    // POST /api/auth/renew
    @PostMapping("/renew")
    public ResponseEntity<?> renew() {
        // Get refreshToken from cookie first, then header
        String refreshTokenFromCookie = null;
        Cookie[] cookies = request.getCookies();
        if (cookies != null) {
            for (Cookie cookie : cookies) {
                if ("refreshToken".equals(cookie.getName())) {
                    refreshTokenFromCookie = cookie.getValue();
                    break;
                }
            }
        }

        // Also check header
        String refreshTokenFromHeader = request.getHeader("refreshToken");

        // Cookie takes precedence if both present
        String refreshTokenValue = refreshTokenFromCookie != null ? refreshTokenFromCookie : refreshTokenFromHeader;

        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Refresh token missing"));
        }

        // Use repository to find the refresh token with locking
        return ResponseEntity.ok().body(renewalLogic(refreshTokenValue));
    }

    // Helper method to do renewal logic
    private String renewalLogic(String refreshTokenValue) {
        // Find the refresh token with lock
        var existingRefresh = tokenRepository.findByTokenValueAndValidRefresh(refreshTokenValue);
        if (existingRefresh.isEmpty()) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Refresh token invalid or expired"));
        }

        TokenEntity oldRefresh = existingRefresh.get();
        // Mark it as revoked
        oldRefresh.setRevoked(true);
        tokenRepository.save(oldRefresh); // This should be in a transaction with new token creation

        // Generate new tokens
        String newRefreshToken = generateToken("REFRESH");
        String newAccessToken = generateToken("ACCESS");
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime newRefreshExpires = now.plusDays(1);
        LocalDateTime newAccessExpires = now.plusMinutes(10);

        tokenRepository.save(new TokenEntity(newRefreshToken, oldRefresh.getUserId(), "REFRESH", now, newRefreshExpires, false, false));
        tokenRepository.save(new TokenEntity(newAccessToken, oldRefresh.getUserId(), "ACCESS", now, newAccessExpires, false, false));

        // Return new access token
        return newAccessToken;
    }

    // POST /api/auth/validate-token
    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        String tokenValue = request.get("token");
        if (tokenValue == null || tokenValue.isEmpty()) {
            return ResponseEntity.status(400).body(new ValidateTokenResponse(false, "Token missing"));
        }

        // Find the token - no locking needed but we want atomic consume
        var token = tokenRepository.findByTokenValue(tokenValue);
        if (token.isEmpty()) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Token not found"));
        }

        TokenEntity tok = token.get();
        if (tok.isRevoked() || tok.getExpiresAt().isBefore(LocalDateTime.now()) || tok.isConsumed()) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Token invalid"));
        }

        // Atomically consume
        tok.setConsumed(true);
        tokenRepository.save(tok);

        return ResponseEntity.ok().body(new ValidateTokenResponse(true, "Token validated and consumed"));
    }

    // POST /api/auth/logout
    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader("Authorization") String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Authorization header missing or invalid"));
        }
        String accessTokenValue = authHeader.replace("Bearer ", "");

        // Validate access token exists and is valid
        var access = tokenRepository.findByTokenValueAndValidAccess(accessTokenValue);
        if (access.isEmpty()) {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Access token invalid"));
        }

        TokenEntity validAccess = access.get();
        String userId = validAccess.getUserId();

        // Revoke all tokens for this user
        tokenRepository.revokeAllTokensByUser(userId);

