package com.auth.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "tokens")
public class TokenEntity {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String tokenValue;
    private String userId;
    private String tokenType; // ACCESS, REFRESH, ONETIME
    private LocalDateTime issuedAt;
    private LocalDateTime expiresAt;
    private boolean isRevoked;
    private boolean isConsumed;

    public TokenEntity() {}

    public TokenEntity(String tokenValue, String userId, String tokenType, LocalDateTime issuedAt, 
                      LocalDateTime expiresAt, boolean isRevoked, boolean isConsumed) {
        this.tokenValue = tokenValue;
        this.userId = userId;
        this.tokenType = tokenType;
        this.issuedAt = issuedAt;
        this.expiresAt = expiresAt;
        this.isRevoked = isRevoked;
        this.isConsumed = isConsumed;
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getTokenValue() { return tokenValue; }
    public void setTokenValue(String tokenValue) { this.tokenValue = tokenValue; }
    public String getUserId() { return userId; }
    public void setUserId(String userId) { this.userId = userId; }
    public String getTokenType() { return tokenType; }
    public void setTokenType(String tokenType) { this.tokenType = tokenType; }
    public LocalDateTime getIssuedAt() { return issuedAt; }
    public void setIssuedAt(LocalDateTime issuedAt) { this.issuedAt = issuedAt; }
    public LocalDateTime getExpiresAt() { return expiresAt; }
    public void setExpiresAt(LocalDateTime expiresAt) { this.expiresAt = expiresAt; }
    public boolean isRevoked() { return isRevoked; }
    public void setRevoked(boolean revoked) { this.isRevoked = revoked; }
    public boolean isConsumed() { return isConsumed; }
    public void setConsumed(boolean consumed) { this.isConsumed = consumed; }
}

