package com.auth.scheduler;

import com.auth.repository.TokenRepository;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.util.List;

@Component
public class CleanupScheduler {

    private final TokenRepository tokenRepository;

    public CleanupScheduler(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    @Scheduled(fixedRate = 10000) // Every 10 seconds
    public void cleanup() {
        List<TokenEntity> expiredTokens = tokenRepository.findAllExpiredOrRevokedOrConsumed();
        int deletedCount = 0;
        for (TokenEntity token : expiredTokens) {
            tokenRepository.delete(token);
            deletedCount++;
        }
        System.out.println("[CLEANUP] Deleted " + deletedCount + " tokens");
    }
}

