package com.auth.controller;

import com.auth.dto.LoginRequest;
import com.auth.dto.LoginResponse;
import com.auth.dto.RenewResponse;
import com.auth.dto.ValidateTokenResponse;
import com.auth.entity.TokenEntity;
import com.auth.repository.TokenRepository;
import com.auth.service.AuthService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;
    private final TokenRepository tokenRepository;

    public AuthController(AuthService authService, TokenRepository tokenRepository) {
        this.authService = authService;
        this.tokenRepository = tokenRepository;
    }

    // POST /api/auth/login
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        if (request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body(Map.of("error", "Username and password must be non-empty"));
        }

        LoginResponse response = authService.login(request.getUsername(), request.getPassword());
        // Set refresh token cookie
        Cookie refreshTokenCookie = new Cookie("refreshToken", response.getRefreshToken());
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400); // 24 hours

        return ResponseEntity.ok()
            .cookie(refreshTokenCookie)
            .body(response); // body contains accessToken and oneTimeToken
    }

    // POST /api/auth/renew
    @PostMapping("/renew")
    public ResponseEntity<?> renew() {
        // Get refreshToken from cookie first
        String refreshTokenFromCookie = null;
        HttpServletRequest requestHttp = (HttpServletRequest) request;
        if (requestHttp.getCookies() != null) {
            for (var cookie : requestHttp.getCookies()) {
                if ("refreshToken".equals(cookie.getName())) {
                    refreshTokenFromCookie = cookie.getValue();
                    break;
                }
            }
        }

        // Also check header
        String refreshTokenFromHeader = request.getHeader("refreshToken");

        // Cookie takes precedence if both present
        String refreshTokenValue = refreshTokenFromCookie != null ? refreshTokenFromCookie : refreshTokenFromHeader;

        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Refresh token missing"));
        }

        RenewResponse renewResp = authService.renew(refreshTokenValue);
        // Return new access token in JSON body as {"accessToken": "..."}
        Map<String, String> response = new HashMap<>();
        response.put("accessToken", renewResp.getAccessToken());
        // Set new refresh token cookie
        Cookie newRefreshCookie = new Cookie("refreshToken", renewResp.getRefreshToken());
        newRefreshCookie.setHttpOnly(true);
        newRefreshCookie.setMaxAge(86400);
        return ResponseEntity.ok()
            .cookie(newRefreshCookie)
            .body(response);
    }

    // POST /api/auth/validate-token
    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        String tokenValue = request.get("token");
        if (tokenValue == null || tokenValue.isEmpty()) {
            return ResponseEntity.status(400).body(new ValidateTokenResponse(false, "Token parameter missing"));
        }

        boolean isValid = authService.validateOneTimeToken(tokenValue);
        if (isValid) {
            return ResponseEntity.ok().body(new ValidateTokenResponse(true, "Token validated and consumed"));
        } else {
            return ResponseEntity.status(401).body(new ValidateTokenResponse(false, "Token invalid"));
        }
    }

    // POST /api/auth/logout
    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader("Authorization") String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Authorization header missing or invalid"));
        }
        String accessTokenValue = authHeader.replace("Bearer ", "");

        // Validate access token exists and is valid
        var access = tokenRepository.findByTokenValueAndValidAccess(accessTokenValue);
        if (access.isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Access token invalid"));
        }

        TokenEntity validAccess = access.get();
        String userId = validAccess.getUserId();

        // Revoke all tokens for this user
        authService.logout(accessTokenValue, userId);

        return ResponseEntity.ok().body(Map.of("message", "Logged out successfully"));
    }
}
EOF"}

