package com.auth.service;

import com.auth.dto.LoginResponse;
import com.auth.entity.TokenEntity;
import com.auth.repository.TokenRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    // Login - generates tokens atomically
    @Transactional
    public LoginTokens login(String username, String password) {
        // Check credentials - accept any non-empty username and password combination
        if (username == null || username.isEmpty() || password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Username and password must be non-empty");
        }

        // Generate random tokens
        String accessToken = generateToken("ACCESS");
        String refreshToken = generateToken("REFRESH");
        String oneTimeToken = generateToken("ONETIME");

        LocalDateTime now = LocalDateTime.now();
        LocalDateTime accessExpires = now.plusMinutes(10);
        LocalDateTime refreshExpires = now.plusDays(1);
        LocalDateTime oneTimeExpires = now.plusMinutes(5);

        // Store all tokens atomically
        tokenRepository.save(new TokenEntity(accessToken, username, "ACCESS", now, accessExpires, false, false));
        tokenRepository.save(new TokenEntity(refreshToken, username, "REFRESH", now, refreshExpires, false, false));
        tokenRepository.save(new TokenEntity(oneTimeToken, username, "ONETIME", now, oneTimeExpires, false, false));

        return new LoginTokens(accessToken, refreshToken, oneTimeToken);
    }

    // Renew - returns both newAccessToken and newRefreshToken
    @Transactional
    public RenewResponse renew(String refreshTokenValue) {
        // Find the refresh token with lock
        var existingRefresh = tokenRepository.findByTokenValueAndValidRefresh(refreshTokenValue);
        if (existingRefresh.isEmpty()) {
            throw new RuntimeException("Refresh token invalid or expired");
        }

        TokenEntity oldRefresh = existingRefresh.get();
        // Mark it as revoked
        oldRefresh.setRevoked(true);
        tokenRepository.save(oldRefresh); // Update in DB

        // Generate new tokens
        String newRefreshToken = generateToken("REFRESH");
        String newAccessToken = generateToken("ACCESS");
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime newRefreshExpires = now.plusDays(1);
        LocalDateTime newAccessExpires = now.plusMinutes(10);

        tokenRepository.save(new TokenEntity(newRefreshToken, oldRefresh.getUserId(), "REFRESH", now, newRefreshExpires, false, false));
        tokenRepository.save(new TokenEntity(newAccessToken, oldRefresh.getUserId(), "ACCESS", now, newAccessExpires, false, false));

        return new RenewResponse(newAccessToken, newRefreshToken);
    }

    // Validate one-time token - returns true if valid and consumed
    @Transactional
    public boolean validateOneTimeToken(String tokenValue) {
        // Find the token
        var token = tokenRepository.findByTokenValue(tokenValue);
        if (token.isEmpty()) {
            return false;
        }

        TokenEntity tok = token.get();
        if (tok.isRevoked() || tok.getExpiresAt().isBefore(LocalDateTime.now()) || tok.isConsumed()) {
            return false;
        }

        // Atomically consume
        tok.setConsumed(true);
        tokenRepository.save(tok);
        return true;
    }

    // Logout - revoke all tokens for user after validating access token
    @Transactional
    public void logout(String accessTokenValue, String userId) {
        // Validate access token exists and belongs to this user
        var access = tokenRepository.findByTokenValueAndValidAccess(accessTokenValue);
        if (access.isEmpty()) {
            throw new RuntimeException("Access token invalid");
        }

        TokenEntity validAccess = access.get();
        if (!validAccess.getUserId().equals(userId)) {
            throw new RuntimeException("Access token belongs to different user");
        }

        // Revoke all tokens for this user
        tokenRepository.revokeAllTokensByUser(userId);
    }

    private String generateToken(String type) {
        return java.util.UUID.randomUUID().toString();
    }

    // Helper classes
    public static class LoginTokens {
        private String accessToken;
        private String refreshToken;
        private String oneTimeToken;

        public LoginTokens(String accessToken, String refreshToken, String oneTimeToken) {
            this.accessToken = accessToken;
            this.refreshToken = refreshToken;
            this.oneTimeToken = oneTimeToken;
        }
        public String getAccessToken() { return accessToken; }
        public String getRefreshToken() { return refreshToken; }
        public String getOneTimeToken() { return oneTimeToken; }
    }

    public static class RenewResponse {
        private String accessToken;
        private String refreshToken;

        public RenewResponse(String accessToken, String refreshToken) {
            this.accessToken = accessToken;
            this.refreshToken = refreshToken;
        }
        public String getAccessToken() { return accessToken; }
        public String getRefreshToken() { return refreshToken; }
    }
}
